import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# &packet.ServerBoundDataStore{Update: protocol.DataStoreUpdate{
# DataStoreName: "inventory", Property: "hotbar", Path: "slots/0",
# ControlType: protocol.DataStoreControlString, StringValue: "diamond_sword",
# PropertyUpdateCount: 300, PathUpdateCount: 4294967294}}
STRING = bytes.fromhex(
    "09696e76656e746f727906686f7462617207736c6f74732f30020d6469616d6f6e645f73776f72642c010000feffffff"
)

# generated by gophertunnel b8bd735:
# &packet.ServerBoundDataStore{Update: protocol.DataStoreUpdate{
# DataStoreName: "hud", Property: "opacity", Path: "",
# ControlType: protocol.DataStoreControlDouble, DoubleValue: 0.5,
# PropertyUpdateCount: 1, PathUpdateCount: 0}}
DOUBLE = bytes.fromhex("03687564076f7061636974790000000000000000e03f0100000000000000")

# generated by gophertunnel b8bd735:
# &packet.ServerBoundDataStore{Update: protocol.DataStoreUpdate{
# DataStoreName: "hud", Property: "visible", Path: "",
# ControlType: protocol.DataStoreControlBoolean, BoolValue: true,
# PropertyUpdateCount: 1, PathUpdateCount: 0}}
BOOL = bytes.fromhex("036875640776697369626c650001010100000000000000")

GOLDENS = [
    pytest.param(
        v2225.ServerboundDataStorePacket(
            update=v2225.DataStoreUpdate(
                data_store_name="inventory",
                property="hotbar",
                path="slots/0",
                data="diamond_sword",
                property_update_count=300,
                path_update_count=4294967294,
            )
        ),
        STRING,
        id="string",
    ),
    pytest.param(
        v2225.ServerboundDataStorePacket(
            update=v2225.DataStoreUpdate(
                data_store_name="hud",
                property="opacity",
                path="",
                data=0.5,
                property_update_count=1,
                path_update_count=0,
            )
        ),
        DOUBLE,
        id="double",
    ),
    pytest.param(
        v2225.ServerboundDataStorePacket(
            update=v2225.DataStoreUpdate(
                data_store_name="hud",
                property="visible",
                path="",
                data=True,
                property_update_count=1,
                path_update_count=0,
            )
        ),
        BOOL,
        id="bool",
    ),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_serverbound_data_store_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_serverbound_data_store_decodes_from_its_golden(packet, golden):
    assert v2225.ServerboundDataStorePacket.from_bytes(golden) == packet
